begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.login(i integer) returns void language plpgsql as $$ begin
 perform set_config('role','authenticated',true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub','44000000-0000-4000-8000-'||lpad(i::text,12,'0'),'role','authenticated')::text,true);
end $$;
insert into auth.users(instance_id,id,aud,role,email,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,confirmation_token,email_change,email_change_token_new,recovery_token)
select '00000000-0000-0000-0000-000000000000',('44000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'authenticated','authenticated','ux-test-'||i||'@example.test','{}','{}',now(),now(),'','','','' from generate_series(1,3) i;
select is(app.decision_end_of_day('2027-03-28','Europe/London'),'2027-03-28 22:59:59+00'::timestamptz,'London spring DST end of day');
select is(app.decision_end_of_day('2027-10-31','Europe/London'),'2027-10-31 23:59:59+00'::timestamptz,'London autumn DST end of day');
select is(app.decision_end_of_day('2027-03-14','America/Los_Angeles'),'2027-03-15 06:59:59+00'::timestamptz,'LA spring DST end of day');
select is(app.decision_end_of_day('2027-11-07','America/Los_Angeles'),'2027-11-08 07:59:59+00'::timestamptz,'LA autumn DST end of day');
select is(app.decision_end_of_day('2027-10-20','Pacific/Kiritimati'),'2027-10-20 09:59:59+00'::timestamptz,'UTC+14 final second');
select is(app.decision_end_of_day(null,'Europe/London'),null::timestamptz,'Optional date remains null');
select pg_temp.login(1);
create temp table profiles as select p, public.create_project('UX '||p,'Europe/London','GBP',current_date,null,p) id from unnest(enum_range(null::public.project_profile)) p;
select is((select count(*)::int from public.project_areas where project_id in(select id from profiles)),0,'All seven profiles create zero Category rows');
create temp table ctx as select id from profiles where p='group_trip';
create temp table links as select public.ensure_project_join_link((select id from ctx)) token;
select is(public.ensure_project_join_link((select id from ctx)),(select token from links),'Repeated copy preserves active token');
select lives_ok($$select public.disable_project_join_link((select id from ctx))$$,'Disable works');
select is(public.resolve_project_join_link((select token from links))->>'state','unavailable','Disabled token invalid');
select isnt(public.ensure_project_join_link((select id from ctx)),(select token from links),'Copy after disable issues a new token');
select is(public.resolve_project_join_link((select token from links))->>'state','unavailable','Old token remains invalid after reissue');
create temp table dec as select public.create_decision_date((select id from ctx),'When?',null,'2099-10-20','[{"title":"A"},{"title":"B"}]') id;
select is((select voting_deadline from public.decisions where id=(select id from dec)),('2099-10-21'::timestamp at time zone 'Europe/London')-interval '1 second','RPC uses stored project timezone');
select lives_ok($$select public.edit_decision((select id from dec),'When?',null,'2099-10-21 12:34:56+00',null)$$,'Legacy API remains supported');
select lives_ok($$select public.edit_decision_date((select id from dec),'Updated title',null,'2099-10-22',null,true)$$,'Preserve old deadline during title edit');
select is((select voting_deadline from public.decisions where id=(select id from dec)),'2099-10-21 12:34:56+00'::timestamptz,'Historical time preserved exactly');
select lives_ok($$select public.edit_decision_date((select id from dec),'Updated title',null,'2099-10-22',null,false)$$,'Explicit date edit normalized');
select is((select voting_deadline from public.decisions where id=(select id from dec)),('2099-10-23'::timestamp at time zone 'Europe/London')-interval '1 second','Edited date final second');
select throws_ok($$select public.create_decision_date((select id from ctx),'Past',null,'2000-01-01','[{"title":"A"},{"title":"B"}]')$$,'22023',null,'Past date guard retained');
create temp table paypal as select public.save_my_payment_link('paypal','HTTPS://PAYPAL.ME/Example') id;
select is((select display_label from public.user_payment_links where id=(select id from paypal)),'PayPal','Canonical provider label');
select is((select payment_url from public.user_payment_links where id=(select id from paypal)),'https://paypal.me/Example','PayPal normalization preserves handle case');
select lives_ok($$select public.save_my_payment_link('monzo','https://monzo.me/example')$$,'Multiple enabled providers');
select lives_ok($$select public.save_my_payment_link('revolut','https://revolut.me/example')$$,'Revolut regression');
select lives_ok($$select public.save_my_payment_link('custom','https://pay.example.com/path','Custom')$$,'Custom regression');
select is((select count(*)::int from public.list_my_payment_links() where is_enabled),4,'All methods remain enabled');
select throws_ok($$select public.save_my_payment_link('paypal','https://paypal.me.evil.com/Example')$$,'P0001',null,'Spoofed host denied');
select throws_ok($$select public.save_my_payment_link('paypal','http://paypal.me/Example')$$,'P0001',null,'HTTP denied');
select throws_ok($$select public.save_my_payment_link('paypal','https://paypal.me/Example/50')$$,'P0001',null,'Amount-specific links denied');
select throws_ok($$select public.save_my_payment_link('paypal','https://paypal.me/Example?next=evil')$$,'P0001',null,'PayPal query denied');
select throws_ok($$select public.save_my_payment_link('paypal','https://paypal.me/')$$,'P0001',null,'Empty handle denied');
set local role postgres;
insert into public.project_members(project_id,user_id,display_name,role,status)
select ctx.id,('44000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'UX member',case when i=3 then 'viewer' else 'member' end::public.member_role,'active' from ctx,generate_series(2,3) i;
select pg_temp.login(2);
select throws_ok($$select public.ensure_project_join_link((select id from ctx))$$,'42501',null,'Member cannot manage invite links');
select throws_ok($$select public.edit_decision_date((select id from dec),'Other',null,null,null,false)$$,'42501',null,'Unrelated Member cannot edit Decision');
select is((select count(*)::int from public.user_payment_links),0,'Other user cannot read personal payment links');
select throws_ok($$select public.save_my_payment_link('paypal','https://paypal.me/Other',null,(select id from paypal))$$,'42501',null,'Cross-user editing denied');
select pg_temp.login(3);
select throws_ok($$select public.ensure_project_join_link((select id from ctx))$$,'42501',null,'Viewer cannot manage invite links');
select throws_ok($$select public.create_decision_date((select id from ctx),'Viewer',null,null,'[{"title":"A"},{"title":"B"}]')$$,'42501',null,'Viewer cannot create Decision');
select pg_temp.login(1);
update public.projects set status='archived' where id=(select id from ctx);
select throws_ok($$select public.ensure_project_join_link((select id from ctx))$$,'42501',null,'Archived copy cannot create or expose a token');
select throws_ok($$select public.edit_decision_date((select id from dec),'Archived',null,null,null,true)$$,'42501',null,'Archived Decision edit denied');
select * from finish();
rollback;
